document.addEventListener('DOMContentLoaded', () => {
initThemeToggle();
initNavbar();
initParticles();
initCounters();
initSearch();
initAutoSubmitFilters();
initDashboardCards();
initAnimations();
initDetailTools();
initBackToTop();
});
function initThemeToggle() {
const toggle = document.getElementById('themeToggle');
if (!toggle) return;
const html = document.documentElement;
const systemTheme = typeof window.matchMedia === 'function'
? window.matchMedia('(prefers-color-scheme: dark)')
: null;
const applyTheme = (theme, persist = false) => {
const safeTheme = theme === 'dark' ? 'dark' : 'light';
html.setAttribute('data-theme', safeTheme);
toggle.setAttribute('aria-label', safeTheme === 'dark' ? 'Açık temaya geç' : 'Koyu temaya geç');
toggle.setAttribute('title', safeTheme === 'dark' ? 'Açık temaya geç' : 'Koyu temaya geç');
if (persist) {
try { localStorage.setItem('obd-theme-preference', safeTheme); } catch (_) {}
}
updateParticleColors(safeTheme);
};
let hasUserPreference = false;
try {
const preference = localStorage.getItem('obd-theme-preference');
hasUserPreference = preference === 'light' || preference === 'dark';
} catch (_) {}
applyTheme(html.getAttribute('data-theme'));
toggle.addEventListener('click', () => {
hasUserPreference = true;
const next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
applyTheme(next, true);
});
const followSystemTheme = event => {
if (!hasUserPreference) applyTheme(event.matches ? 'dark' : 'light');
};
if (systemTheme) {
if (typeof systemTheme.addEventListener === 'function') {
systemTheme.addEventListener('change', followSystemTheme);
} else if (typeof systemTheme.addListener === 'function') {
systemTheme.addListener(followSystemTheme);
}
}
}
function updateParticleColors(theme) {
const particles = document.querySelectorAll('.bg-particle');
const darkColors = ['#3b82f6', '#8b5cf6', '#06b6d4', '#a855f7'];
const lightColors = ['#059669', '#047857', '#0d9488', '#10b981'];
const colors = theme === 'light' ? lightColors : darkColors;
particles.forEach(p => {
const color = colors[Math.floor(Math.random() * colors.length)];
p.style.background = `radial-gradient(circle, ${color}20 0%, transparent 70%)`;
});
}
function initNavbar() {
const navbar = document.getElementById('navbar');
const navToggle = document.getElementById('navToggle');
const navLinks = document.getElementById('navLinks');
window.addEventListener('scroll', () => {
if (window.scrollY > 20) {
navbar.classList.add('scrolled');
} else {
navbar.classList.remove('scrolled');
}
});
if (navToggle && navLinks) {
navToggle.addEventListener('click', () => {
navLinks.classList.toggle('active');
navToggle.classList.toggle('active');
});
navLinks.querySelectorAll('.nav-link').forEach(link => {
link.addEventListener('click', () => {
navLinks.classList.remove('active');
navToggle.classList.remove('active');
});
});
}
}
function initParticles() {
const container = document.getElementById('bgParticles');
if (!container) return;
if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
if (window.matchMedia('(max-width: 640px)').matches) return;
const theme = document.documentElement.getAttribute('data-theme');
const darkColors = ['#3b82f6', '#8b5cf6', '#06b6d4', '#a855f7'];
const lightColors = ['#059669', '#047857', '#0d9488', '#10b981'];
const colors = theme === 'light' ? lightColors : darkColors;
const particleCount = 6;
for (let i = 0; i < particleCount; i++) {
const particle = document.createElement('div');
particle.className = 'bg-particle';
const size = Math.random() * 300 + 200;
const color = colors[Math.floor(Math.random() * colors.length)];
particle.style.width = `${size}px`;
particle.style.height = `${size}px`;
particle.style.background = `radial-gradient(circle, ${color}20 0%, transparent 70%)`;
particle.style.left = `${Math.random() * 100}%`;
particle.style.top = `${Math.random() * 100}%`;
particle.style.animationDelay = `${Math.random() * -20}s`;
particle.style.animationDuration = `${15 + Math.random() * 15}s`;
container.appendChild(particle);
}
}
function initCounters() {
const statValues = document.querySelectorAll('.stat-value[data-target]');
if (!statValues.length) return;
const observer = new IntersectionObserver((entries) => {
entries.forEach(entry => {
if (entry.isIntersecting) {
animateCounter(entry.target);
observer.unobserve(entry.target);
}
});
}, { threshold: 0.5 });
statValues.forEach(el => observer.observe(el));
}
function animateCounter(el) {
const target = parseInt(el.getAttribute('data-target'));
const duration = 1500;
const start = performance.now();
function update(currentTime) {
const elapsed = currentTime - start;
const progress = Math.min(elapsed / duration, 1);
const eased = 1 - Math.pow(1 - progress, 3);
const current = Math.floor(eased * target);
el.textContent = current;
if (progress < 1) {
requestAnimationFrame(update);
} else {
el.textContent = target;
}
}
requestAnimationFrame(update);
}
function initSearch() {
const heroInput = document.getElementById('heroSearchInput');
const pageInput = document.getElementById('pageSearchInput');
const suggestionsBox = document.getElementById('searchSuggestions');
const inputs = [heroInput, pageInput].filter(Boolean);
inputs.forEach(input => {
let debounceTimer;
input.addEventListener('input', () => {
clearTimeout(debounceTimer);
debounceTimer = setTimeout(() => {
const query = input.value.trim();
if (query.length >= 2) {
fetchSuggestions(query, input);
} else {
hideSuggestions(input);
}
}, 200);
});
input.addEventListener('focus', () => {
const query = input.value.trim();
if (query.length >= 2) {
fetchSuggestions(query, input);
}
});
document.addEventListener('click', (e) => {
if (!e.target.closest('.hero-search') && !e.target.closest('.page-search')) {
hideSuggestions(input);
}
});
});
}
function fetchSuggestions(query, input) {
fetch(`/api/search?q=${encodeURIComponent(query)}&limit=6`)
.then(res => res.json())
.then(data => {
showSuggestions(data, input);
})
.catch(() => {});
}
function showSuggestions(results, input) {
const form = input.closest('form');
const box = form && form.querySelector('.search-suggestions');
if (!box) return;
box.replaceChildren();
if (!Array.isArray(results) || !results.length) {
box.classList.remove('active');
return;
}
const fragment = document.createDocumentFragment();
results.forEach(item => {
const category = /^[PBCU]$/.test(String(item.category || '')) ? item.category : 'P';
const code = String(item.code || '').toUpperCase();
const link = document.createElement('a');
link.href = '/kod/' + encodeURIComponent(code);
link.className = 'suggestion-item';
const badge = document.createElement('span');
badge.className = 'code-badge category-' + category;
badge.textContent = category;
const codeLabel = document.createElement('span');
codeLabel.className = 'suggestion-code';
codeLabel.textContent = code;
const name = document.createElement('span');
name.className = 'suggestion-name';
name.textContent = String(item.name || '');
link.append(badge, codeLabel, name);
fragment.appendChild(link);
});
box.appendChild(fragment);
box.classList.add('active');
}
function hideSuggestions(input) {
const form = input.closest('form');
if (!form) return;
const box = form.querySelector('.search-suggestions');
if (box) box.classList.remove('active');
}
function initAnimations() {
const animateElements = document.querySelectorAll(
'.stat-card, .code-card, .category-card, .result-card, .detail-card, .about-card, .related-card'
);
if (!animateElements.length) return;
const observer = new IntersectionObserver((entries) => {
entries.forEach((entry, index) => {
if (entry.isIntersecting) {
entry.target.style.animationDelay = `${index * 0.05}s`;
entry.target.classList.add('fade-in');
observer.unobserve(entry.target);
}
});
}, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });
animateElements.forEach(el => {
el.style.opacity = '0';
observer.observe(el);
});
}
function initAutoSubmitFilters() {
document.querySelectorAll('[data-auto-submit]').forEach(control => {
control.addEventListener('change', () => {
if (control.form) control.form.requestSubmit();
});
});
}
function initDashboardCards() {
document.querySelectorAll('[data-dashboard-url]').forEach(card => {
const openCard = () => {
const target = card.getAttribute('data-dashboard-url');
if (target && target.startsWith('/gosterge-paneli/')) window.location.assign(target);
};
card.addEventListener('click', event => {
if (!event.target.closest('a')) openCard();
});
card.addEventListener('keydown', event => {
if (event.key === 'Enter' || event.key === ' ') {
event.preventDefault();
openCard();
}
});
});
}
function showSiteToast(message) {
const toast = document.getElementById('siteToast');
if (!toast) return;
toast.textContent = message;
toast.classList.add('visible');
window.clearTimeout(showSiteToast.timer);
showSiteToast.timer = window.setTimeout(() => toast.classList.remove('visible'), 2200);
}
function initDetailTools() {
const copyButton = document.querySelector('[data-copy-code]');
const shareButton = document.querySelector('[data-share-code]');
if (copyButton) {
copyButton.addEventListener('click', async () => {
const code = copyButton.getAttribute('data-copy-code');
try {
await navigator.clipboard.writeText(code);
showSiteToast(code + ' panoya kopyalandı');
} catch (_) {
showSiteToast('Kod kopyalanamadı');
}
});
}
if (shareButton) {
shareButton.addEventListener('click', async () => {
const shareData = {
title: shareButton.getAttribute('data-share-title') || document.title,
text: shareButton.getAttribute('data-share-code') + ' OBD-II arıza kodu',
url: window.location.href,
};
try {
if (navigator.share) await navigator.share(shareData);
else {
await navigator.clipboard.writeText(window.location.href);
showSiteToast('Sayfa bağlantısı kopyalandı');
}
} catch (error) {
if (error && error.name !== 'AbortError') showSiteToast('Paylaşım başlatılamadı');
}
});
}
}
function initBackToTop() {
const button = document.getElementById('backToTop');
if (!button) return;
const update = () => button.classList.toggle('visible', window.scrollY > 700);
window.addEventListener('scroll', update, { passive: true });
button.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
update();
}